<script lang="ts">
 import {onMount} from 'svelte'; import L from 'leaflet'; import type {GeoJsonObject,Feature} from 'geojson'; import type {Persona,RealParkFeature} from '../types/municipality'; import {parkName,scoreColor,scoreField,valueFor} from '../lib/realMunicipality';
 let {parks,persona,selectedId,onHover,onLeave,onSelect}:{parks:RealParkFeature[];persona:Persona;selectedId:string|null;onHover:(p:RealParkFeature)=>void;onLeave:()=>void;onSelect:(p:RealParkFeature)=>void}=$props();
 let container:HTMLDivElement;let map:L.Map;let layer:L.GeoJSON;
 function draw(){if(!map)return;layer?.remove();const byId=new Map(parks.map(p=>[p.properties.park_id,p]));layer=L.geoJSON({type:'FeatureCollection',features:parks} as GeoJsonObject,{style:(feature)=>{const park=byId.get(String(feature?.properties?.park_id));const score=park?valueFor(park,scoreField(persona)):null;return{color:park?.properties.park_id===selectedId?'#173e34':'#ffffff',weight:park?.properties.park_id===selectedId?3:1,fillColor:scoreColor(score),fillOpacity:.72};},onEachFeature:(feature:Feature,shape)=>{const park=byId.get(String(feature.properties?.park_id));if(!park)return;const path=shape as L.Path;shape.bindTooltip(`${parkName(park)} · ${valueFor(park,scoreField(persona))?.toFixed(1)??'Unknown'}`,{sticky:true});shape.on('mouseover',()=>{path.setStyle({weight:3,color:'#173e34',fillOpacity:.9});onHover(park)});shape.on('mouseout',()=>{layer.resetStyle(shape);onLeave()});shape.on('click',()=>onSelect(park));}}).addTo(map);}
 onMount(()=>{map=L.map(container,{zoomControl:false}).setView([55.7047,13.1910],13);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(map);draw();const observer=new ResizeObserver(()=>map.invalidateSize());observer.observe(container);return()=>{observer.disconnect();map.remove()}});$effect(()=>{parks;persona;selectedId;draw()});
</script>
<div class="map-shell real-map-shell"><div class="score-legend" aria-label="Persona score colour legend"><strong>Score</strong><span><i class="unknown"></i>Unknown</span><span><i class="low"></i>0–24</span><span><i class="fair"></i>25–49</span><span><i class="good"></i>50–74</span><span><i class="high"></i>75–100</span></div><div class="map" bind:this={container} aria-label="Interactive map of 172 Lund park polygons"></div></div>
